const raw = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const store = $getWorkflowStaticData('global');
store.known_error_hashes = (store.known_error_hashes && typeof store.known_error_hashes === 'object') ? store.known_error_hashes : {};

const now = new Date();
function pad(n) { return String(n).padStart(2, '0'); }
function dateKey(d) { return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; }
function stamp(d) { return `${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}T${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`; }
function redact(value) {
  let s = typeof value === 'string' ? value : JSON.stringify(value ?? '');
  s = s.replace(/Bearer\s+[A-Za-z0-9._\-]+/gi, 'Bearer REDACTED');
  s = s.replace(/(access_token=)[^&\s]+/gi, '$1REDACTED');
  s = s.replace(/("access_token"\s*:\s*")[^"]+/gi, '$1REDACTED');
  s = s.replace(/("Authorization"\s*:\s*")[^"]+/gi, '$1REDACTED');
  s = s.replace(/(sk-proj-[A-Za-z0-9_\-]+)/g, 'REDACTED');
  s = s.replace(/([0-9]{8,12}:[A-Za-z0-9_\-]{25,})/g, 'REDACTED');
  s = s.replace(/([A-Za-z0-9_\-]{90,})/g, 'REDACTED');
  return s;
}

const logType = String(raw.log_type || (raw.is_error === true || raw.status === 'error' || !!raw.error ? 'error' : 'execution'));
const errorHash = String(raw.error_hash || '').trim().replace(/[^A-Za-z0-9_\-]/g, '');
const workflowName = String(raw.workflow_name || raw.workflowName || 'workflow').replace(/[^A-Za-z0-9_\-]/g, '_');
const executionId = String(raw.execution_id || raw.executionId || 'exec').replace(/[^A-Za-z0-9_\-]/g, '_');
const dateStr = dateKey(now);
const ts = stamp(now);

// Dedup: for debug_report, suppress if same error_hash seen in last 48h
let skipWrite = false;
let skipReason = '';
if (logType === 'debug_report' && errorHash) {
  const cutoff = now.getTime() - 48 * 60 * 60 * 1000;
  for (const [k, v] of Object.entries(store.known_error_hashes)) {
    if (Date.parse(v) < cutoff) delete store.known_error_hashes[k];
  }
  if (store.known_error_hashes[errorHash]) {
    skipWrite = true;
    skipReason = 'duplicate_error_hash';
  } else {
    store.known_error_hashes[errorHash] = now.toISOString();
  }
}

// custom_path override: direct write to any repo path
if (raw.custom_path && typeof raw.custom_path === 'string') {
  const safePath = String(raw.custom_path).replace(/\.\./g, '').replace(/^\//, '');
  const isError2 = false;
  const payload2 = { captured_at: now.toISOString(), log_type: 'custom', source: String(raw.source || 'n8n'), custom_path: safePath, data: raw };
  const sanitized2 = JSON.parse(redact(JSON.stringify(payload2)));
  return [{ json: { ...sanitized2, skip_write: false, skip_reason: '', github_path: safePath, github_error_path: '', github_content: (() => { const rc = raw.content; if (rc !== undefined) return typeof rc === 'string' ? rc : JSON.stringify(rc, null, 2); return JSON.stringify(sanitized2, null, 2); })(), commit_message: String(raw.commit_message || `meta: ${safePath}`) } }];
}

// Path routing by log_type
let primaryPath;
if (logType === 'debug_report') {
  primaryPath = `debug-reports/auto_debugger/${dateStr}/${errorHash || ts}_debug.json`;
} else if (logType === 'workflow_export') {
  primaryPath = `workflows/${workflowName}.json`;
} else if (logType === 'backup') {
  primaryPath = `backups/${dateStr}/${workflowName}_backup_${ts}.json`;
} else {
  primaryPath = `logs/executions/${dateStr}/${ts}_${workflowName}_${executionId}.json`;
}
const errorPath = `logs/errors/${dateStr}/${ts}_${workflowName}_${executionId}_${errorHash || 'nohash'}.json`;

const isError = logType === 'error' || raw.is_error === true || raw.status === 'error' || !!raw.error;

const payload = {
  captured_at: now.toISOString(),
  log_type: logType,
  source: String(raw.source || 'n8n'),
  workflow_name: workflowName,
  workflow_id: String(raw.workflow_id || raw.workflowId || ''),
  execution_id: executionId,
  status: String(raw.status || (isError ? 'error' : 'success')),
  is_error: isError,
  error_hash: errorHash,
  data: raw,
};
const sanitized = JSON.parse(redact(JSON.stringify(payload)));

return [{
  json: {
    ...sanitized,
    skip_write: skipWrite,
    skip_reason: skipReason,
    github_path: primaryPath.replace(/[^A-Za-z0-9_.\/\-]/g, '_'),
    github_error_path: errorPath.replace(/[^A-Za-z0-9_.\/\-]/g, '_'),
    github_content: JSON.stringify(sanitized, null, 2),
    commit_message: `${logType === 'debug_report' ? 'debug' : logType === 'backup' ? 'backup' : logType === 'workflow_export' ? 'export' : 'log'}: ${workflowName} ${logType} ${ts}`,
  }
}];

const upstream = $('Prepare GitHub Log').first().json;
return [{
  json: {
    ...$input.first().json,
    is_error: upstream.is_error,
    github_error_path: upstream.github_error_path,
    github_content: upstream.github_content,
    commit_message: upstream.commit_message,
  }
}];

const prepared = $('Prepare GitHub Log').first().json;
const current = ($input.first() && $input.first().json) ? $input.first().json : {};
return [{
  json: {
    ok: true,
    logger: 'actual_08_github_logger',
    result: prepared.skip_write ? 'skipped' : 'logged',
    skip_write: Boolean(prepared.skip_write),
    skip_reason: prepared.skip_reason || '',
    log_type: prepared.log_type || current.log_type || '',
    github_path: prepared.github_path || current.github_path || '',
    is_error: Boolean(prepared.is_error),
    captured_at: new Date().toISOString()
  }
}];
